var StorageService = {
	getTransactions() {
		try {
			const data = localStorage.getItem(STORAGE_KEYS.TRANSACTIONS);
			if (!data) {
				const initial = getStarterTransactions();
				localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(initial));
				return initial;
			}
			const parsed = JSON.parse(data);
			let migrated = false;
			const updated = parsed.map((tx) => {
				if (tx.categoryId === "cat_veg_fruits") {
					migrated = true;
					return {
						...tx,
						categoryId: "cat_vegetables"
					};
				}
				return tx;
			});
			if (migrated) localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(updated));
			return updated;
		} catch (e) {
			console.error("Failed to read transactions from storage:", e);
			return getStarterTransactions();
		}
	},
	saveTransaction(tx) {
		const all = this.getTransactions();
		const now = (/* @__PURE__ */ new Date()).toISOString();
		if (tx.id) {
			const index = all.findIndex((t) => t.id === tx.id);
			if (index !== -1) {
				const updated = {
					...all[index],
					...tx,
					id: tx.id,
					updatedAt: now
				};
				all[index] = updated;
				localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(all));
				if (updated.type !== "transfer" && updated.categoryId && updated.description) this.learnDescriptionCategory(updated.description, updated.categoryId);
				return updated;
			}
		}
		const newTx = {
			...tx,
			id: tx.id || `tx_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
			createdAt: now,
			updatedAt: now
		};
		all.unshift(newTx);
		localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(all));
		if (newTx.type !== "transfer" && newTx.categoryId && newTx.description) this.learnDescriptionCategory(newTx.description, newTx.categoryId);
		return newTx;
	},
	deleteTransaction(id) {
		const all = this.getTransactions();
		const target = all.find((t) => t.id === id);
		if (!target) return { success: false };
		const remaining = all.filter((t) => t.id !== id);
		localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(remaining));
		localStorage.setItem(STORAGE_KEYS.LAST_DELETED, JSON.stringify(target));
		return {
			success: true,
			deletedTx: target
		};
	},
	undoDeleteTransaction() {
		try {
			const raw = localStorage.getItem(STORAGE_KEYS.LAST_DELETED);
			if (!raw) return null;
			const tx = JSON.parse(raw);
			const all = this.getTransactions();
			all.unshift(tx);
			localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(all));
			localStorage.removeItem(STORAGE_KEYS.LAST_DELETED);
			return tx;
		} catch {
			return null;
		}
	},
	moveTransactionProfile(txId, newProfileId) {
		const all = this.getTransactions();
		const index = all.findIndex((t) => t.id === txId);
		if (index === -1) return null;
		all[index] = {
			...all[index],
			profileId: newProfileId,
			updatedAt: (/* @__PURE__ */ new Date()).toISOString()
		};
		localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(all));
		return all[index];
	},
	duplicateTransaction(txId) {
		const all = this.getTransactions();
		const source = all.find((t) => t.id === txId);
		if (!source) return null;
		const copy = {
			...source,
			id: `tx_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`,
			description: `${source.description} (Copy)`,
			createdAt: (/* @__PURE__ */ new Date()).toISOString(),
			updatedAt: (/* @__PURE__ */ new Date()).toISOString()
		};
		all.unshift(copy);
		localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(all));
		return copy;
	},
	getProfiles() {
		try {
			const data = localStorage.getItem(STORAGE_KEYS.PROFILES);
			if (!data) {
				localStorage.setItem(STORAGE_KEYS.PROFILES, JSON.stringify(DEFAULT_PROFILES));
				return DEFAULT_PROFILES;
			}
			return JSON.parse(data);
		} catch {
			return DEFAULT_PROFILES;
		}
	},
	saveProfile(profile) {
		const profiles = this.getProfiles();
		const index = profiles.findIndex((p) => p.id === profile.id);
		if (index >= 0) profiles[index] = profile;
		else profiles.push(profile);
		localStorage.setItem(STORAGE_KEYS.PROFILES, JSON.stringify(profiles));
		return profiles;
	},
	deleteProfile(id) {
		if (id === "home" || id === "office") return {
			success: false,
			message: "Default Home and Office profiles cannot be deleted."
		};
		if (this.getTransactions().some((t) => t.profileId === id)) return {
			success: false,
			message: "This profile contains transactions. Archive it or move transactions first."
		};
		const remaining = this.getProfiles().filter((p) => p.id !== id);
		localStorage.setItem(STORAGE_KEYS.PROFILES, JSON.stringify(remaining));
		return { success: true };
	},
	getCategories() {
		try {
			const data = localStorage.getItem(STORAGE_KEYS.CATEGORIES);
			if (!data) {
				localStorage.setItem(STORAGE_KEYS.CATEGORIES, JSON.stringify(DEFAULT_CATEGORIES));
				return DEFAULT_CATEGORIES;
			}
			let list = JSON.parse(data);
			let hasChanges = false;
			list = list.map((cat) => {
				if (cat.id === "cat_veg_fruits") {
					hasChanges = true;
					return {
						...cat,
						id: "cat_vegetables",
						name: "Vegetables",
						nameHi: "सब्जियां (Vegetables)",
						icon: "Carrot"
					};
				}
				if (cat.id === "cat_milk" && cat.name !== "Milk") {
					hasChanges = true;
					return {
						...cat,
						name: "Milk",
						nameHi: "दूध (Milk)",
						icon: "Milk"
					};
				}
				if (cat.id === "cat_petrol" && cat.name !== "Petrol") {
					hasChanges = true;
					return {
						...cat,
						name: "Petrol",
						nameHi: "पेट्रोल (Petrol)",
						icon: "Fuel"
					};
				}
				return cat;
			});
			const existingIds = new Set(list.map((c) => c.id));
			for (const def of DEFAULT_CATEGORIES) if (!existingIds.has(def.id)) {
				list.push(def);
				hasChanges = true;
			}
			if (hasChanges) localStorage.setItem(STORAGE_KEYS.CATEGORIES, JSON.stringify(list));
			return list;
		} catch {
			return DEFAULT_CATEGORIES;
		}
	},
	saveCategory(cat) {
		const list = this.getCategories();
		const index = list.findIndex((c) => c.id === cat.id);
		if (index >= 0) list[index] = cat;
		else list.push(cat);
		localStorage.setItem(STORAGE_KEYS.CATEGORIES, JSON.stringify(list));
		return list;
	},
	deleteCategory(id) {
		if (this.getTransactions().some((t) => t.categoryId === id)) return {
			success: false,
			message: "Category cannot be deleted because historical transactions use it. You can Archive it instead."
		};
		const remaining = this.getCategories().filter((c) => c.id !== id);
		localStorage.setItem(STORAGE_KEYS.CATEGORIES, JSON.stringify(remaining));
		return { success: true };
	},
	getAccounts() {
		try {
			const data = localStorage.getItem(STORAGE_KEYS.ACCOUNTS);
			if (!data) {
				localStorage.setItem(STORAGE_KEYS.ACCOUNTS, JSON.stringify(DEFAULT_ACCOUNTS));
				return DEFAULT_ACCOUNTS;
			}
			return JSON.parse(data);
		} catch {
			return DEFAULT_ACCOUNTS;
		}
	},
	saveAccount(acc) {
		const accounts = this.getAccounts();
		const index = accounts.findIndex((a) => a.id === acc.id);
		if (index >= 0) accounts[index] = acc;
		else accounts.push(acc);
		localStorage.setItem(STORAGE_KEYS.ACCOUNTS, JSON.stringify(accounts));
		return accounts;
	},
	getSettings() {
		try {
			const data = localStorage.getItem(STORAGE_KEYS.SETTINGS);
			if (!data) {
				localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(DEFAULT_SETTINGS));
				return DEFAULT_SETTINGS;
			}
			return {
				...DEFAULT_SETTINGS,
				...JSON.parse(data)
			};
		} catch {
			return DEFAULT_SETTINGS;
		}
	},
	saveSettings(settings) {
		const merged = {
			...this.getSettings(),
			...settings
		};
		localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify(merged));
		return merged;
	},
	resetAllData() {
		localStorage.removeItem(STORAGE_KEYS.TRANSACTIONS);
		localStorage.removeItem(STORAGE_KEYS.PROFILES);
		localStorage.removeItem(STORAGE_KEYS.CATEGORIES);
		localStorage.removeItem(STORAGE_KEYS.ACCOUNTS);
		localStorage.removeItem(STORAGE_KEYS.SETTINGS);
		localStorage.removeItem(STORAGE_KEYS.LAST_DELETED);
		this.getProfiles();
		this.getCategories();
		this.getAccounts();
		this.getTransactions();
		this.getSettings();
	},
	exportDatabaseSnapshot() {
		return {
			version: 2,
			exportTimestamp: (/* @__PURE__ */ new Date()).toISOString(),
			appName: "Day-to-day Expenses",
			profiles: this.getProfiles(),
			categories: this.getCategories(),
			accounts: this.getAccounts(),
			transactions: this.getTransactions(),
			settings: this.getSettings()
		};
	},
	restoreDatabaseSnapshot(snapshot) {
		if (!snapshot || typeof snapshot !== "object") return {
			success: false,
			message: "Invalid backup format"
		};
		if (!Array.isArray(snapshot.transactions) || !Array.isArray(snapshot.categories)) return {
			success: false,
			message: "Missing transaction or category tables in backup file"
		};
		localStorage.setItem(STORAGE_KEYS.PROFILES, JSON.stringify(snapshot.profiles || DEFAULT_PROFILES));
		localStorage.setItem(STORAGE_KEYS.CATEGORIES, JSON.stringify(snapshot.categories || DEFAULT_CATEGORIES));
		localStorage.setItem(STORAGE_KEYS.ACCOUNTS, JSON.stringify(snapshot.accounts || DEFAULT_ACCOUNTS));
		localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(snapshot.transactions));
		if (snapshot.settings) localStorage.setItem(STORAGE_KEYS.SETTINGS, JSON.stringify({
			...DEFAULT_SETTINGS,
			...snapshot.settings
		}));
		return {
			success: true,
			count: snapshot.transactions.length
		};
	},
	getDescriptionCategoryMap() {
		try {
			const data = localStorage.getItem(STORAGE_KEYS.DESC_CATEGORY_MAP);
			if (!data) {
				localStorage.setItem(STORAGE_KEYS.DESC_CATEGORY_MAP, JSON.stringify(DEFAULT_KEYWORD_MAPPINGS));
				return { ...DEFAULT_KEYWORD_MAPPINGS };
			}
			return {
				...DEFAULT_KEYWORD_MAPPINGS,
				...JSON.parse(data)
			};
		} catch {
			return { ...DEFAULT_KEYWORD_MAPPINGS };
		}
	},
	learnDescriptionCategory(description, categoryId) {
		if (!description || !categoryId || categoryId === "transfer_internal") return;
		const cleanDesc = description.trim().toLowerCase();
		if (!cleanDesc) return;
		const currentMap = this.getDescriptionCategoryMap();
		currentMap[cleanDesc] = categoryId;
		const words = cleanDesc.split(/[\s,.\-_/]+/).filter((w) => w.length >= 3);
		for (const w of words) currentMap[w] = categoryId;
		try {
			localStorage.setItem(STORAGE_KEYS.DESC_CATEGORY_MAP, JSON.stringify(currentMap));
		} catch (e) {
			console.warn("Failed to save description category mapping:", e);
		}
	},
	suggestCategoryForDescription(text) {
		if (!text) return null;
		const clean = text.trim().toLowerCase();
		if (!clean) return null;
		const map = this.getDescriptionCategoryMap();
		if (map[clean]) return map[clean];
		const words = clean.split(/[\s,.\-_/]+/).filter((w) => w.length >= 3);
		for (const w of words) if (map[w]) return map[w];
		for (const [key, catId] of Object.entries(map)) if (clean.includes(key) || key.length >= 4 && key.includes(clean)) return catId;
		return null;
	}
};
